window.K3_QRAW.push.apply(window.K3_QRAW, [
  {"id": "kc|edu-psych|xl-02|知识点四|7", "bank": "kc", "subj": "edu-psych", "ch": "xl-02", "chName": "第二章 学习及其理论解释", "sec": "知识点四：认知主义学习理论", "no": 7, "q": "学生已经知道了质量的概念，再学习热量，这种学习方式是（　）", "opts": ["上位学习", "下位学习", "组合学习", "机械学习"], "a": 2, "exp": "此题考查奥苏伯尔的认知同化过程。A.上位学习：新概念、新命题具有广泛的包容范围或较高的概括水平，将一系列已有观念包含于其下而获得意义。B.下位学习：将概括程度或包容范围较低的新概念或命题，归属到认知结构中原有的包容范围或概括水平较高的适当命题或概念之下，从而获得新概念或新命题的意义。C.组合学习：既不产生下位关系又不产生上位关系的学习。√D.干扰选项，与本题无关。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 101}},
  {"id": "kc|edu-psych|xl-02|知识点四|8", "bank": "kc", "subj": "edu-psych", "ch": "xl-02", "chName": "第二章 学习及其理论解释", "sec": "知识点四：认知主义学习理论", "no": 8, "q": "学生在学习杠杆是在力的作用下可以绕固定点转动的硬棒后，再学习定滑轮时，老师强调定滑轮虽然不是硬棒，但也是一种特殊的杠杆，这属于（　）", "opts": ["派生类属学习", "相关类属学习", "并列学习", "总括学习"], "a": 1, "exp": "此题考查奥苏伯尔的认知同化理论。A.派生类属学习：新知识是已有概念的特例，可直接纳人原有概念，不改变原有概念的内涵。定滑轮不完全符合“硬棒”特征，不是简单特例。B.相关类属学习：新知识扩展、修正或限定原有概念，使原有概念的内涵发生一定变化。题干中，学生先学“杠杆”的定义，再学“定滑轮”一特殊的杠杆，此时，原有“杠杆”概念（必须是硬棒）被修正和扩展为“本质上绕固定点转动的机械”，这是相关类属学习。√C.并列学习：新旧知识无上下位关系，此处定滑轮属于杠杆的下位概念，不是并列。D.总括学习：先学具体例子再概括上位概念（上位学习），与题干方向相反。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 101}},
  {"id": "kc|edu-psych|xl-02|知识点四|9", "bank": "kc", "subj": "edu-psych", "ch": "xl-02", "chName": "第二章 学习及其理论解释", "sec": "知识点四：认知主义学习理论", "no": 9, "q": "在学习“平行四边形”概念后，教师让学生观察不同形状的四边形（如长方形、菱形、一般平行四边形），并引导他们归纳这些图形的共同特征，最终概括总结出“两组对边平行且相等的四边形是平行四边形”的结论。根据奥苏伯尔的学习分类，这属于（　）", "opts": ["有意义的接受学习", "有意义的发现学习", "机械的接受学习", "机械的发现学习"], "a": 1, "exp": "此题考查奥苏伯尔的学习分类。奥苏伯尔根据两个维度划分学习：学习方式（接受学习/发现学习）、学习性质（有意义学习／机械学习）（1）题干中学生不是被动接受定义，而是在教师引导下观察实例并自已归纳概括，这是发现学习。（2）新旧知识（四边形、平行、边等概念）与原有认知建立了非任意的、实质性的联系，因此是有意义学习。综上，这是有意义的发现学习。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 101}},
  {"id": "kc|edu-psych|xl-02|知识点四|10", "bank": "kc", "subj": "edu-psych", "ch": "xl-02", "chName": "第二章 学习及其理论解释", "sec": "知识点四：认知主义学习理论", "no": 10, "q": "下列学习情境中，最能体现奥苏伯尔提出的“有意义的接受学习”的是（　）", "opts": ["小学生通过反复背诵乘法口诀来记住计算结果", "幼儿在玩要中偶然发现磁铁能吸住铁制品", "初中生在物理课上通过教师的讲解理解了“浮力原理”后，能解释轮船为何能漂浮", "高中生通过刷题形成了对数学公式的条件反射"], "a": 2, "exp": "此题考查奥苏伯尔的有意义接受说。A.小学生通过反复背诵乘法口诀记住了计算结果，但并未真正理解其意义，属于机械的接受学习。·B.幼儿自主探索磁铁特性，形成了对“磁铁有特殊吸引力”的新认知，属于有意义的发现学习。C.初中生通过教师的讲解理解了“浮力原理”，并建立了新旧知识之间的联系，属于有意义的接受学习。√D.高中生通过刷题形成了对数学公式的条件反射，但缺乏对数学原理的真正理解，属于机械的接受学习。·加涅、认知负荷理论、多媒体学习原理。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 101}},
  {"id": "kc|edu-psych|xl-02|知识点四|11", "bank": "kc", "subj": "edu-psych", "ch": "xl-02", "chName": "第二章 学习及其理论解释", "sec": "知识点四：认知主义学习理论", "no": 11, "q": "加涅、认知负荷理论、多媒体学习原理。要使信息从短时记忆进人长时记忆必须经过（　）", "opts": ["应用", "检索", "编码", "提取"], "a": 2, "exp": "此题考查加涅的信息加工模型。A.应用：属于知识的迁移阶段，并非记忆存储的必要环节。B.检索：从长时记忆中提取信息的过程，属于信息的输出阶段，而非信息进人长时记忆的过程。C.编码：促进信息保持并顺利进人长时记忆的重要前提条件，与题干符合。√D.提取：与检索同义，不是信息进人长时记忆的条件。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 102}},
  {"id": "kc|edu-psych|xl-02|知识点四|12", "bank": "kc", "subj": "edu-psych", "ch": "xl-02", "chName": "第二章 学习及其理论解释", "sec": "知识点四：认知主义学习理论", "no": 12, "q": "一位博物馆参观者在导游快速讲解时，能准确复述刚听到的“公元前221年，秦始皇统一六国”这句话，但几分钟后便忘记了具体年份，只记得“秦朝建立于两千多年前”。根据信息加工理论，参观者最)，而几分钟后的概括性记忆则体现了（）的工作。初准确复述主要依赖于（　）", "opts": ["瞬时记忆；短时记忆", "短时记忆；长时记忆", "瞬时记忆；长时记忆", "短时记忆；瞬时记忆"], "a": 1, "exp": "此题考查加涅的信息加工模型。（1）瞬时记忆（感觉登记）：仅持续0.25～2秒，无法支持完整复述句子。A、C选项将复述归因于瞬时记忆，忽视了短时记忆的主动加工，排除A、C选项。（2）短时记忆：保持时间约2.5～20秒，容量有限，可通过复述维持。“准确复述刚听到的内容”属于短时记忆。（3）长时记忆：经过加工后的长期存储系统；会对信息进行意义编码和简化整合。几分钟后遗忘细节，但保留意义化概括（“两千多年前”），说明信息经过编码进入长时记忆。D选项混淆了短时记忆与瞬时记忆的持续时间，排除D选项。因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 102}},
  {"id": "kc|edu-psych|xl-02|知识点四|13", "bank": "kc", "subj": "edu-psych", "ch": "xl-02", "chName": "第二章 学习及其理论解释", "sec": "知识点四：认知主义学习理论", "no": 13, "q": "在实验课上，李老师边讲解操作要点边进行分步示范，随后要求学生通过反复默读、闭眼复述操作步骤的方式加深记忆，并尝试回忆关键操作环节。这一教学安排综合体现了加涅信息加工学习理论中的（　）", "opts": ["动机阶段、概括阶段、反馈阶段", "动机阶段、保持阶段、回忆阶段", "领会阶段、保持阶段、回忆阶段", "领会阶段、概括阶段、保持阶段"], "a": 2, "exp": "此题考查加涅的信息加工学习理论。（1）李老师边讲解操作要点边进行分步示范，有助于学生理解操作的关键环节和步骤，对应的是领会阶段。（2）李老师要求学生反复默读、闭眼复述操作步骤，目的是让学生通过言语复述的方式强化记忆，这有助于学生将所学知识从短时记忆转入长时记忆，对应的是保持阶段。（3）尝试回忆关键操作环节需要学生从长时记忆中提取之前所学的信息，对应的是回忆阶段。因此，答案选C。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 102}},
  {"id": "kc|edu-psych|xl-02|知识点四|14", "bank": "kc", "subj": "edu-psych", "ch": "xl-02", "chName": "第二章 学习及其理论解释", "sec": "知识点四：认知主义学习理论", "no": 14, "q": "在教学设计中，以下哪种方法最有助于降低认知负荷？（　）", "opts": ["增加学习材料的难度", "采用大量的文字说明", "使用图表和实例辅助教学", "加快教学进度"], "a": 2, "exp": "此题考查认知负荷理论。A/D.增加学习材料的难度/加快教学进度会增加认知负荷（内在+外加）。B.采用大量的文字说明可能使学习材料更复杂，增加外加认知负荷。C.使用图表和实例辅助教学可以使学习材料更直观，降低外加认知负荷，从而有助于学习。√", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 102}},
  {"id": "kc|edu-psych|xl-02|知识点四|15", "bank": "kc", "subj": "edu-psych", "ch": "xl-02", "chName": "第二章 学习及其理论解释", "sec": "知识点四：认知主义学习理论", "no": 15, "q": "在多媒体教学中，采用“动画+解说”的方式，比传统文字说明的方式更利于理解，这体现了（　）", "opts": ["双重编码原理", "认知负荷原理", "先行组织者原理", "发现教学原理"], "a": 2, "exp": "此题考查认知负荷理论。A.内在认知负荷：内在负荷由材料本质决定，绘图任务不改变材料本身的复杂性。B.外在认知负荷：外在负荷源自设计缺陷，而绘图是教学设计中的有益任务，非干扰性缺陷。C.关联认知负荷：“绘制时间轴”是典型的生成性学习策略，通过组织信息促进意义建构，也叫生成认知负荷。√D.元认知负荷：对认知过程的监控与调节，如规划学习步骤，与具体加工任务不同。干扰选项。务【】A.双重编码原理：图片和文字组合呈现信息，比只使用单一的文字呈现信息更能促进有意义学习的发生。“动画+解说”正是双重编码原理的典型应用，通过言语+非言语双通道的协同加工，实现对知识的更高效理解和存储。√B.认知负荷原理：核心是探讨教学中如何控制认知负荷，即如何避免内在、外在认知负荷，提升关联认知负荷。题干体现的是“两种形式结合更利于理解”的底层编码机制，而非负荷控制本身，因此并非该原理的直接体现。C.先行组织者原理：核心是在学习新知识前，呈现一个抽象、概括性的引导性材料，帮助学生建立新旧知识的联系。题干未涉及“先呈现引导材料”的环节。D.发现教学原理：核心是让学习者通过自主探究、发现的方式获得知识，强调学生的主动性和探究过程。与“动画+解说”的接受方式相悖。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 102}},
  {"id": "kc|edu-psych|xl-02|知识点五|1", "bank": "kc", "subj": "edu-psych", "ch": "xl-02", "chName": "第二章 学习及其理论解释", "sec": "知识点五：建构主义学习理论", "no": 1, "q": "根据认知灵活理论，高级知识的获得主要通过哪种方式？（　）", "opts": ["练习", "反馈", "案例解决", "讲授"], "a": 2, "exp": "此题考查认知灵活理论。A.练习：常针对结构良好领域的知识的熟练化，对高级知识而言不够充分。B.反馈：学习的重要支持，但不是高级知识获得的核心途径。C.案例解决：认知灵活理论主要针对复杂、结构不良领域的高级知识学习。该理论强调：高级知识具有复杂性、情境依赖性和多维性，不能通过简单讲解或机械练习掌握。需要通过多重情境的案例分析与比较，从不同角度、不同背景下反复观察与解决问题，才能形成灵活的知识表征和适应性迁移能力。√D.讲授：多以单一视角传递知识，难以应对复杂领域的情境变化。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 102}},
  {"id": "kc|edu-psych|xl-02|知识点五|2", "bank": "kc", "subj": "edu-psych", "ch": "xl-02", "chName": "第二章 学习及其理论解释", "sec": "知识点五：建构主义学习理论", "no": 2, "q": "医学生在见习期间，通过观察、参与主任医师处理临床病例的行为，接受经验丰富医生的点拨与指导，从而获得了许多医学经验和技能。面对不同的病例，他们可以灵活应用自已的医学知识。这种教学属于（　）", "opts": ["支架式教学", "认知学徒制", "随机通达教学", "互惠式教学"], "a": 1, "exp": "此题考查认知建构主义学习理论。A.支架式教学：强调教师提供临时性支持，随着学生能力提高逐渐撤去“支架”，更侧重于教学过程中B.认知学徒制：强调学习者通过在真实情境中观察专家（如医生）在指导下参与实践、逐渐独立解决问题的过程，获得复杂的、情境化的知识与技能。题干中“观察主任医师处理病例、接受点拨指导、灵活应用医学知识”正是认知学徒制的典型体现。√C.随机通达教学：属于认知灵活理论的应用，强调对复杂概念在不同情境中多次接触、多角度理解，但不强调“师徒式”的观察与指导。D.互惠式教学：用于阅读理解教学的互动策略，强调师生轮流引导讨论，与医学见习中专家指导下的实践模式不同。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 102}},
  {"id": "kc|edu-psych|xl-02|知识点五|3", "bank": "kc", "subj": "edu-psych", "ch": "xl-02", "chName": "第二章 学习及其理论解释", "sec": "知识点五：建构主义学习理论", "no": 3, "q": "新课程倡导研究性学习、合作学习、教学对话等教学方式，其主要理论依据是（　）", "opts": ["建构主义学习论", "结构主义学习论", "认知主义学习论", "行为主义学习论"], "a": 0, "exp": "此题考查建构主义学习理论的观点。A.建构主义学习论：强调学习是学生主动建构知识的过程，注重情境、协作、对话和意义建构。其典型教学方式包括：研究性学习（学生主动探究、建构理解）合作学习（通过社会互动协作建构知识）、教学对话（师生、生生对话促进意义协商）。√B.结构主义学习论：通常指布鲁纳的认知结构理论，强调学科基本结构的掌握与发现学习，虽与研究性学习有关，但合作、对话等社会互动维度不如建构主义突出。C.认知主义学习论：侧重信息加工与内部认知过程，但对合作、情境的强调不及建构主义。D.行为主义学习论：强调刺激一反应和外部强化，与研究性学习、合作学习等主动建构的教学方式明显不符。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 102}},
  {"id": "kc|edu-psych|xl-02|知识点六|1", "bank": "kc", "subj": "edu-psych", "ch": "xl-02", "chName": "第二章 学习及其理论解释", "sec": "知识点六：人本主义学习理论", "no": 1, "q": "董老师总是希望在课堂上尽可能地满足学生爱与被爱的需要。董老师的做法体现了课堂管理的（：（　）", "opts": ["建构取向", "行为取向", "认知取向", "人本取向"], "a": 3, "exp": "此题考查人本主义学习理论。A.建构取向：强调学生在认知上主动建构知识，与课堂管理中的社会互动和意义生成有关，但核心并非满足情感需求。B.行为取向：关注通过强化、惩罚等外部手段塑造学生行为，与情感需求的满足关系不大。C.认知取向：关注学生的信息加工、问题解决等认知过程，也不是以情感需求为中心。D.人本取向：课堂管理强调满足学生的情感需求、尊重学生的尊严与价值，营造支持性、关怀性的课堂氛围。题干中董老师希望满足学生爱与被爱的需要，这直接对应人本主义的思想。√", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 103}},
  {"id": "kc|edu-psych|xl-02|知识点六|2", "bank": "kc", "subj": "edu-psych", "ch": "xl-02", "chName": "第二章 学习及其理论解释", "sec": "知识点六：人本主义学习理论", "no": 2, "q": "马斯洛认为，理想的学校应反对外在学习，倡导内在学习。下列观点中，与这种“内在学习”最为一致的是（　）", "opts": ["接受学习", "发现学习", "认知学习", "经验学习"], "a": 3, "exp": "此题考查马斯洛和罗杰斯的观点。A.接受学习（奥苏伯尔）：以教师讲授为主，学生接受现成知识，可能更偏向外部驱动，不一定符合内在学习。B.发现学习（布鲁纳）：强调学生主动探索、发现知识结构，学生发现的动机有可能是外部奖励，也有可能是内在兴趣。C.认知学习：范围宽泛，包括各种信息加工过程，不特指人本主义的内在动机导向。D.经验学习（罗杰斯）：罗杰斯将学习分为认知学习与经验学习。认知学习只发生在“颈部以上”，只涉及心智，不涉及情感；经验学习是教育者以学生的经验生长为中心，以学生的自发性和主动性为学习动力，把学习与学生的愿望、兴趣和需要有机结合起来。经验学习与马斯洛的“内在学习”观点一致。√", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 103}},
  {"id": "kc|edu-psych|xl-02|知识点六|3", "bank": "kc", "subj": "edu-psych", "ch": "xl-02", "chName": "第二章 学习及其理论解释", "sec": "知识点六：人本主义学习理论", "no": 3, "q": "下列有关罗杰斯的自由学习理论的分析，不正确的是（　）", "opts": ["罗杰斯认为学习有两种，即认知学习和经验学习", "在罗杰斯看来，凡是认知学习都是无意义学习", "罗杰斯所谓的有意义学习是指与学生已有经验有关的学习", "在有意义学习方面，罗杰斯和奥苏伯尔都强调学生的兴趣"], "a": 3, "exp": "此题考查罗杰斯的自由学习理论。D选项中，按照罗杰斯的观点，奥苏伯尔的有意义学习是一种认知学习，实际是无意义的。因为这种学习强调新旧知识之间的联系，它只涉及心智，而不涉及个人意义，是一种发生在“颈部以上的学习”，所以在罗杰斯看来，奥苏伯尔的有意义学习未强调兴趣。此题为选非题，因此，答案选D。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 103}},
  {"id": "kc|edu-psych|xl-03|知识点一|1", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点一：学习动机的分类", "no": 1, "q": "“知之者不如好之者，好之者不如乐之者”，这一论述强调的学习动机类型是（　）", "opts": ["内部动机", "外部动机", "社会交往动机", "情境动机"], "a": 0, "exp": "此题考查学习动机的类型。A.内部动机：人们对学习本身的内在需要所引起的动机。“知之者不如好之者，好之者不如乐之者”表明了学习动机主要来自对学习本身的兴趣，属于内部动机。√B.外部动机：由外部诱因引起的动机。如有的学生学习是为了得到奖励、避免惩罚、取悦教师等。C.社会交往动机：与交往需要相关的动机。D.情境动机：与情境因素密切相关的动机。它是暂时的、不稳定的，往往表现在某一具体学习活动中。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 104}},
  {"id": "kc|edu-psych|xl-03|知识点一|2", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点一：学习动机的分类", "no": 2, "q": "某学生把学习看成获得他人的尊重和仰慕的手段，根据奥苏伯尔对学习动机影响学生学业成就的不同维度划分，这种学习动机是（　）", "opts": ["认知内驱力", "附属内驱力", "自我提高内驱力", "主导内驱力"], "a": 2, "exp": "此题考查奥苏伯尔对学习动机的分类。A.认知内驱力：个体了解、理解和掌握知识，以及系统地阐述问题并解决问题的需要。B.附属内驱力：个体为了获得和保持长者们的赞许或认可而表现出来的把工作做好的一种需要。C.自我提高内驱力：把成就看作赢得地位和自尊的根源。题干中“获得他人的尊重和仰慕”体现了个体对地位和自尊的需要。√D.干扰选项，无此说法。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 104}},
  {"id": "kc|edu-psych|xl-03|知识点一|3", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点一：学习动机的分类", "no": 3, "q": "小明为赢得父母和老师的夸奖而努力学习，该学习动机属于（　）", "opts": ["认知内驱力", "自我提高内驱力", "附属内驱力", "自尊内驱力"], "a": 2, "exp": "此题考查学习动机的分类。小明努力学习的目的是获得父母和老师的夸奖，这是为了获得长者的赞许和认可而表现出的动机，属于附属内驱力。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 104}},
  {"id": "kc|edu-psych|xl-03|知识点一|4", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点一：学习动机的分类", "no": 4, "q": "自我提高内驱力和附属内驱力属于（　）", "opts": ["内部动机", "外部动机", "直接动机", "间接动机"], "a": 1, "exp": "此题考查学习动机的分类。自我提高内驱力是个体因自已的胜任能力或工作能力而获得相应的地位和威望的需要。附属内驱力是个体为了获得长者的赞许和同伴的接纳而表现出来的把学习、工作做好的一种需要。自我提高内驱力和附属内驱力都是一种间接的学习需要，属于外部动机。因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 104}},
  {"id": "kc|edu-psych|xl-03|知识点一|5", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点一：学习动机的分类", "no": 5, "q": "周恩来总理少年时代立志“为中华之崛起而读书”，这种学习动机属于（　）", "opts": ["情境动机", "一般动机", "远景的间接性动机", "近景的直接性动机"], "a": 2, "exp": "此题考查学习动机的分类。近景的直接性动机是指与近期目标相联系的一类动机，是与学习活动直接相连的，源于对学习内容或学习结果的兴趣；远景的间接性动机是指动机行为与长远目标相联系的一类动机。题干中，“为中华之崛起而读书”属于周恩来总理少年时代的长远目标，属于远景的间接性动机。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 104}},
  {"id": "kc|edu-psych|xl-03|知识点一|6", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点一：学习动机的分类", "no": 6, "q": "宋真宗赵恒曾赋诗：“富家不用买良田，书中自有千钟粟。安居不用架高堂，书中自有黄金屋。出门莫恨无人随，书中车马多如簇。娶妻莫恨无良媒，书中自有颜如玉。男儿欲遂平生志，五经勤向窗前读。”这首诗中没有涉及的学习动机是（　）", "opts": ["内部动机", "远景动机", "外部动机", "成就动机"], "a": 0, "exp": "此题考查学习动机的分类。古诗大意：读书考取功名后，自然能得到丰厚的物质回报（千钟粟、黄金屋、车马、颜如玉），从而实现人生志向。A.内部动机：人们对学习本身的内在需要所引起的动机。题干中未体现内部动机。此题为选非题。√B.远景动机：与长远目标相联系的一类动机，它往往与个人的理想、志向、世界观等高层次的心理因深联系微信193163788日素相关。“男儿欲遂平生志”指向通过读书实现长远人生目标（功名利禄），属于远景动机。C.外部动机：由外部诱因引起的动机。“千钟粟、黄金屋”等均属于外部诱因，体现了宋真宗的外部动机。D.成就动机：一种成就需要，指个体对重要成就、技能掌握、控制或者高标准的渴望。“平生志”体现了实现人生抱负的意图，属于成就动机。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 104}},
  {"id": "kc|edu-psych|xl-03|知识点一|7", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点一：学习动机的分类", "no": 7, "q": "根据耶克斯一多德森定律，在一定范围内，学习效率随学习动机强度增加而（　），直至达到学习动机最佳强度而获最佳效率，之后则随学习动机强度的进一步增大而（　）", "opts": ["提高；提高", "提高；不变", "提高；下降", "不变；下降"], "a": 2, "exp": "此题考查学习动机与学习效果的关系。根据耶克斯一多德森定律，学习动机存在一个最佳水平，在一定范围内，学习效率随学习动机强度增加而提高，直至达到学习动机最佳强度而获最佳效率，之后则随学习动机强度的进一步增大而下降。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 104}},
  {"id": "kc|edu-psych|xl-03|知识点一|8", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点一：学习动机的分类", "no": 8, "q": "下列关于学习动机与学习效果的关系，描述正确的是（　）", "opts": ["学习动机是影响学习效果的决定性因素", "学习动机的发展依赖于学习效果", "学习动机的高低直接影响学习效果的好坏", "从事比较容易的学习活动，动机强度的最佳水平点也会低些"], "a": 1, "exp": "此题考查学习动机与学习效果的关系。A.修改：学习动机是影响学习效果的一个重要因素，但不是决定性因素。B.学习动机是有效地进行学习的前提，但学习动机的巩固和发展又依赖于学习效果，二者之间是良性循环。√C.修改：学习动机与学习效果的关系不是直接的，它们之间往往以学习行为为中介。D.修改：动机强度的最佳水平会因任务的难易程度而异。从事比较容易的学习活动，动机强度的最佳水平点会高些。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 105}},
  {"id": "kc|edu-psych|xl-03|知识点一|9", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点一：学习动机的分类", "no": 9, "q": "下列哪种情况下教师最应该避免使用外部诱因？（　）", "opts": ["当学生从事挑战性的任务时", "当任务就学生能力提供了反馈时", "当学生在没有外部诱因的情况下就有工作动机时", "当学生经历了大量的失败时"], "a": 2, "exp": "此题考查学习动机。A、B、D选项的这三种情况都可以使用外部诱因来激发学生的兴趣、给予学生肯定或鼓励。C选项中，学生不需要外部诱因就有工作动机，说明学生的动机是自发的，是不需要通过外部诱因去增强的，学生完成工作，有利于增强学生的自我效能感。因此，答案选C。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 105}},
  {"id": "kc|edu-psych|xl-03|知识点二|1", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点二：学习动机的强化理论、需要层次理论、自由学习理论", "no": 1, "q": "学习动机的强化理论是由（）学习理论家提出来的。（　）", "opts": ["格式塔主义", "行为主义", "认知主义", "建构主义"], "a": 1, "exp": "此题考查学习动机的强化理论。学习动机的强化理论是由行为主义学习理论家提出来的，他们不仅用强化来解释学习的发生，而且用它来解释动机的产生。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 105}},
  {"id": "kc|edu-psych|xl-03|知识点二|2", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点二：学习动机的强化理论、需要层次理论、自由学习理论", "no": 2, "q": "根据马斯洛的需要层次理论，学校里最重要的缺失需要是（　）", "opts": ["生理的需要和安全的需要", "归属与爱的需要和尊重的需要", "求知与理解的需要和美的需要", "自我实现的需要"], "a": 1, "exp": "此题考查马斯洛的需要层次理论。学生在学校里最重要的缺失需要是归属与爱的需要和尊重的需要。学生如果感到没有被人爱，或自认为无能，就不可能有强烈的动机去实现较高的目标。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 105}},
  {"id": "kc|edu-psych|xl-03|知识点二|3", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点二：学习动机的强化理论、需要层次理论、自由学习理论", "no": 3, "q": "在马斯洛的需要层次理论中，具有永不满足的特点的是（　）", "opts": ["归属和爱的需要", "尊重的需要", "生理的需要", "自我实现的需要"], "a": 3, "exp": "此题考查马斯洛的需要层次理论。马斯洛将七种需要分为缺失需要和成长需要。其中，前四种属于缺失需要，它们是我们生存所必需的，一旦缺失需要得到满足，对其需求的强度就会下降；自我实现的需要是成长需要，其特点在于永不满足。因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 105}},
  {"id": "kc|edu-psych|xl-03|知识点二|4", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点二：学习动机的强化理论、需要层次理论、自由学习理论", "no": 4, "q": "李老师在他的课上完全放弃了固定大纲，让学生们自已选择想探究的课题。他主要负责提供资源、营造无条件接纳的课堂氛围，并鼓励学生进行自我评价。这种做法最直接地体现了（　）", "opts": ["自由学习理论", "需要层次理论", "自我决定理论", "自我价值理论"], "a": 0, "exp": "此题考查自由学习理论。A.自由学习理论：教师作为一名促进者为学生营造轻松、没有威胁、相互理解和支持的学习氛围，促自我评价”均体现了自由学习理论。√B.需要层次理论：认为人类的学习动机与各种切身需要紧密相关，且将这些需要划分了层次结构。与深联系微信1931637日8日C.自我决定理论：个体在充分认识个人需要和环境信息的基础上，对行为所做出的自由选择。与题意不符。D.自我价值理论：主要关注个体如何通过成败归因来保护自我价值感。与题意不符。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 105}},
  {"id": "kc|edu-psych|xl-03|知识点三|1", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点三：期望一价值理论（成就动机理论）", "no": 1, "q": "根据成就动机理论，避免失败的人在选择任务时倾向于选择（　）", "opts": ["有一定挑战的任务", "与自己水平相当的任务", "非常容易或非常难的任务", "没主见，看别人怎么选"], "a": 2, "exp": "此题考查阿特金森的成就动机理论。避免失败的人对失败的担心大于获得成功的动机，这种人在选择任务时倾向于选择非常容易或者非常难的任务，因为前者容易成功，而后者即使失败了，也有借口挽回面子。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 105}},
  {"id": "kc|edu-psych|xl-03|知识点三|2", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点三：期望一价值理论（成就动机理论）", "no": 2, "q": "根据阿特金森的期望一价值理论，在面临不同难度的任务时，力求成功的学生与避免失败的学生相比，在选择任务时会倾向于选择（　）", "opts": ["高难度的任务", "中等难度的任务", "低难度的任务", "没有难度的任务"], "a": 1, "exp": "此题考查阿特金森的期望一价值理论。力求成功的学生敢于冒险去尝试并追求成功，更倾向于选择具有一定挑战性的任务，并保证具有一定的成功可能性，因此更倾向于选择难度适中的任务。避免失败的学生也追求成功，但更想避免失败，因此更倾向于选择非常容易或非常难的任务。因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 105}},
  {"id": "kc|edu-psych|xl-03|知识点三|3", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点三：期望一价值理论（成就动机理论）", "no": 3, "q": "关于任务难度与努力程度的关系，以下说法正确的是（　）", "opts": ["任务越简单，越能激励自已努力", "任务越难，越能激励自己努力", "中等难度的任务比太难或太易的任务更容易激励自已努力", "任务难度与努力程度没有关系"], "a": 2, "exp": "此题考查成就动机理论。A.修改：任务越简单，可能越容易完成，但也可能因缺乏挑战而难以激励努力。B.修改：任务越难，容易让人产生畏难情绪或挫败感，不一定激励努力。C.中等难度的任务，既不过于简单令人厌倦，也不过于困难令人气，更容易激发适当的努力程度。√D.修改：任务难度与努力程度在实践中明显相关。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 105}},
  {"id": "kc|edu-psych|xl-03|知识点四|1", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点四：自我效能感理论", "no": 1, "q": "下列对于自我效能感的功能的描述，不正确的是（　）", "opts": ["决定个体对活动的选择及对该活动的坚持性", "影响个体面对困难的态度", "影响活动时的情绪", "与行为的结果无关"], "a": 3, "exp": "此题考查自我效能感理论。（1）自我效能感的功能如下：①决定个体对活动的选择和坚持性；②影响个体面对困难的态度；③影响个体新行为的获得和习得行为的表现；④影响个体在活动时的情绪状态。A、B、C选项说法正确。（2）D选项中，自我效能感是指个体对自已能否成功进行某一成就行为的主观判断，人的行为受行为结果因素与先行因素的影响。此题为选非题，因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 106}},
  {"id": "kc|edu-psych|xl-03|知识点四|2", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点四：自我效能感理论", "no": 2, "q": "根据自我效能感理论，某学生相信只要努力学习就能考上好大学，但他觉得就算自已认真听讲，也很难听懂。这属于（　）", "opts": ["结果期望高，效能期望高", "结果期望低，效能期望低", "结果期望低，效能期望高", "结果期望高，效能期望低"], "a": 3, "exp": "此题考查自我效能感理论。结果期望指人对自已某种行为会导致某一结果（强化）的推测，是传统的期望。效能期望指人对自已能否做出某种行为的能力的推测，即自我效能感。题干中努力学习是行为，能考上好大学是结果，故结果期望高；觉得很难听懂是推测自已能力低，故效能期望低。因此，答案选D。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 106}},
  {"id": "kc|edu-psych|xl-03|知识点五|1", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点五：成败归因理论", "no": 1, "q": "在归因训练中，老师要求学生尽量尝试“努力归因”，以增强他们的自信心。因为在韦纳的成败归因理论中，努力属于（　）", "opts": ["内部的、不稳定的、可控的因素", "内部的、不稳定的、不可控的因素", "内部的、稳定的、可控的因素", "内部的、稳定的、不可控的因素"], "a": 0, "exp": "此题考查韦纳的成败归因理论。韦纳将人们对于成败的归因分为三个维度、六个方面，三个维度即内部性、稳定性和可控性，六个方面包括能力高低、努力程度、任务难度、运气好坏、身心状态、外界环境。努力程度属于内部的、不稳定的、可控的因素。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 106}},
  {"id": "kc|edu-psych|xl-03|知识点五|2", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点五：成败归因理论", "no": 2, "q": "小叶在多次考试前尝试了不同的复习策略，但成绩均不理想，于是她的学习态度变得消极，甚至在课上发呆、睡觉。这可能是因为她将成绩不佳归因于（　）", "opts": ["能力不足", "运气不佳", "努力不够", "试卷太难"], "a": 0, "exp": "此题考查韦纳的成败归因理论。A.能力不足：内在、稳定、不可控，这种归因容易让人感到努力无法改变结果，从而放弃努力。题干中小叶尝试过不同复习策略后成绩均不理想，且出现放弃行为，这可能因为她将失败归因于自已的能力不足。√B.运气不佳：外在、不稳定、不可控，但通常不会导致长期消极态度。C.努力不够：内在、不稳定、可控，这种归因不会让人完全放弃，因为可以增加努力。D.试卷太难：外在、稳定、不可控，但通常不会导致完全否定自已的长期能力。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 106}},
  {"id": "kc|edu-psych|xl-03|知识点五|3", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点五：成败归因理论", "no": 3, "q": "根据韦纳的归因理论，下列结论错误的是（　）", "opts": ["在付出同样努力时，能力低的，应得到更少的奖励", "能力低而努力的人应受到最高评价", "引导学生将学业成败归于内部的、不稳定的和可控的原因", "归因于努力相比于归因于能力，无论成功或失败，都会引发更强烈的情绪体验"], "a": 0, "exp": "此题考查韦纳的成败归因理论。A选项中，在付出同样努力时，能力低的，应得到更多的奖励。此题为选非题，因此，答案选A。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 106}},
  {"id": "kc|edu-psych|xl-03|知识点五|4", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点五：成败归因理论", "no": 4, "q": "某学生认为自己由于贪玩，课上总是开小差，因此导致考试失利。这种归因属于（　）", "opts": ["内部、不可控和不稳定归因", "内部、可控和稳定归因", "内部、不可控和稳定归因", "内部、可控和不稳定归因"], "a": 3, "exp": "此题考查韦纳的成败归因理论。选D。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 106}},
  {"id": "kc|edu-psych|xl-03|知识点五|5", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点五：成败归因理论", "no": 5, "q": "一名运动员将比赛失败归因为“裁判不公”。根据归因理论，这种归因可能导致该运动员（　）", "opts": ["提高自身的情绪调节能力", "提高后续训练的投入度", "建立稳定的自我评价标准", "忽视自身的技术缺陷"], "a": 3, "exp": "此题考查归因理论。根据归因理论，将比赛失败归因为“裁判不公”属于外部的、不稳定的、不可控的归因。这种归因方式可能会使运动员将失败归因于外部因素，认为失败不是自己的问题，从而忽视自身的技术缺陷。因此，答案选D。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 106}},
  {"id": "kc|edu-psych|xl-03|知识点六|1", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点六：目标定向理论（成就目标理论）", "no": 1, "q": "关于成就目标定向与内隐能力观之间的关系，下列表述正确的是（　）", "opts": ["掌握目标的学生持能力不变观", "掌握目标的学生持能力发展观", "表现目标的学生持能力发展观", "表现目标的学生持能力有限观"], "a": 1, "exp": "此题考查目标定向理论。掌握目标的学生持能力发展观，表现目标的学生持能力不变观。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 106}},
  {"id": "kc|edu-psych|xl-03|知识点六|2", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点六：目标定向理论（成就目标理论）", "no": 2, "q": "根据目标定向理论，某学生为了不给小组拖后腿，尤其怕自已技不如人，在同桌的帮助下最终学会了物理实验操作步骤，该学生具有（　）", "opts": ["掌握趋近目标", "掌握回避目标", "表现趋近目标", "表现回避目标"], "a": 3, "exp": "此题考查目标定向理论。A.掌握趋近目标：着眼于掌握知识、完成任务，获得比自己过去高的能力或者胜任任务的能力。与题意不符。B.掌握回避目标：着眼于避免跟自己相比、跟任务相比显得自己无能，避免任务没有完成或者内容没被掌握。与题意不符。C.表现趋近目标：着眼于展现自已的能力，做到比别人优秀，根据常模标准来判断自已的表现。与题意不符。D.表现回避目标：着眼于避免在别人面前表现差劲，避免跟别人相比显示自己无能。题干中，该学生为了避免给小组拖后腿，怕自己技不如人，因此是为了避免跟同学相比显示自己无能而学习。√", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 106}},
  {"id": "kc|edu-psych|xl-03|知识点六|3", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点六：目标定向理论（成就目标理论）", "no": 3, "q": "研究发现，课堂目标结构能影响学生的动机水平。其中，竞争型的课堂结构能激发学生以（为中心的动机系统。（　）", "opts": ["社会目标", "表现目标", "掌握目标", "发展目标"], "a": 1, "exp": "此题考查目标定向理论。在竞争型的课堂结构中，学生关注的是自己与他人的比较结果，更注重外在表现，目的是显示自己的能力，获得他人的认可或超过他人，所以能激发学生以表现目标为中心的动机系统。因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 107}},
  {"id": "kc|edu-psych|xl-03|知识点六|4", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点六：目标定向理论（成就目标理论）", "no": 4, "q": "某学生选择那些比较简单的单词来背，以成为背单词最多的学生，这类学生属于（　）", "opts": ["自我卷人的学习者", "能力卷人的学习者", "成功卷人的学习者", "任务卷人的学习者"], "a": 0, "exp": "此题考查目标定向理论。A.自我卷入的学习者：设置表现目标，学习是为了做给别人看或向别人证明自己的能力。题干中所描述的学生属于自我卷人的学习者。√B/C.干扰选项。D.任务卷入的学习者：设置掌握目标，学习是为了个人的成长，而不是为了跟别人相比。他们关心的是能否掌握，而不是表现是否出众。他们在学习中会更多地寻求帮助，使用较高水平的认知策略，运用更有效的学习方法。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 107}},
  {"id": "kc|edu-psych|xl-03|知识点六|5", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点六：目标定向理论（成就目标理论）", "no": 5, "q": "在一项数学竞赛中，四位同学的表现各不相同。其中，体现了掌握回避目标的是（　）", "opts": ["小刘希望自己在比赛中获得第一名，以此证明自已比其他同学聪明", "小马反复计算数据，担心因计算错误而暴露自己的知识漏洞", "小赵担心被其他同学认为能力不足，因而在比赛前不断练习", "小周主动研究其他解题方法，希望能真正掌握知识"], "a": 1, "exp": "此题考查目标定向理论。A.小刘着眼于展现自己的能力，做到比别人优秀，属于表现趋近目标。B.小马着眼于避免跟自已相比、跟任务相比感到自己无能，避免任务没有完成或者内容没被掌握，属于掌握回避目标。√C.小赵着眼于避免在别人面前表现差劲，避免跟别人相比显得自已无能，属于表现回避目标。D.小周着眼于掌握知识、完成任务，获得比自已过去强的能力或者胜任任务的能力，属于掌握趋近目标。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 107}},
  {"id": "kc|edu-psych|xl-03|知识点七|1", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点七：自我决定理论", "no": 1, "q": "甜甜有过一次在全班同学面前唱歌跑调的经历，为了不在全班同学面前出，她下定决心要努力练习唱歌。根据学习动机的自我决定理论，这属于外部动机中的（　）", "opts": ["外部调节", "内摄调节", "认同调节", "整合调节"], "a": 1, "exp": "此题考查自我决定理论的动机分类。A.外部调节：个体为了满足外在要求（获得奖励或避免惩罚）而服从外部规则做出的某种行为。B.内摄调节：个体吸收了外部规则，但没有将其完全接纳为自我的一部分，个体是为了避免焦虑或羞愧，或维护自尊和自我价值，而做出某种行为。题干中，甜甜下定决心要努力练习唱歌是为了维护个人自尊，体现了内摄调节。√C.认同调节：个体认同规则的价值，觉得遵循规则是重要的，自愿按照规则做出行为。D.整合调节：个体将外部规则完全内化，成为自我的一部分。在各种活动中自主地做出规则所要求的行为。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 107}},
  {"id": "kc|edu-psych|xl-03|知识点七|2", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点七：自我决定理论", "no": 2, "q": "根据有机整合理论，学生喜欢学习新的数学知识，享受做数学题，认为解题过程本身就能带来无限快乐，一旦在实际生活中应用数学知识就感到兴奋。这种学习动机属于（　）", "opts": ["无动机", "外部动机", "内部动机", "内化动机"], "a": 2, "exp": "此题考查有机整合理论的动机类型。有机整合理论将人的动机看作一个从无动机、外部动机到内部动机的自我决定程度不断增加的连续体。A.无动机者处于缺少行为意愿的状态，可能是由于个体觉得行为结果不重要，即使做了也得不到想要的结果，或者自己没有能力做出这个行为。B.外部动机者不是出于对活动本身的兴趣，而是为了获得某种可分离的结果而去从事一项活动。C.内部动机者从事活动是为了活动本身的乐趣，是发自内心想做这项活动，在做的过程中感到快乐和享受，与题意相符。√D.干扰选项，无此说法。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 107}},
  {"id": "kc|edu-psych|xl-03|知识点七|3", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点七：自我决定理论", "no": 3, "q": "根据自我决定理论，下列行为中，最有可能削弱学生内在动机的是（　）", "opts": ["对学生的进步给予具体反馈，如“你这道题的解题思路很清晰", "允许学生自主制订学习计划，并对计划执行情况进行讨论", "承诺学生“若期末考进班级前十，就奖励一部手机", "创造合作学习氛围，让学生在小组中获得归属感"], "a": 2, "exp": "此题考查自我决定理论。A.肯定学生解题思路的具体反馈，满足了学生的能力需要（胜任需要），有助于增强其内在动机。B.允许学生自主制订学习计划，满足了学生的自主需要，有助于增强其内在动机。C.以奖励手机为条件激励学生学习，属于外部奖励。这种做法可能使学生的学习动机从“对学习本身的兴趣”转向“为获得奖励而学习”，从而削弱其内在动机。√D.创造合作学习氛围，满足了学生的关系需要（归属需要），有利于维持和增强其内在动机。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 107}},
  {"id": "kc|edu-psych|xl-03|知识点八|1", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点八：自我价值理论", "no": 1, "q": "根据自我价值理论，持有“60分万岁，多一分浪费”观点的学生属于（　）", "opts": ["高趋低避型", "高趋高避型", "低趋高避型", "低趋低避型"], "a": 2, "exp": "此题考查自我价值理论。A.高趋低避型：这类学生被称为“乐观主义者”“成功定向者”“掌握定向者”，通常表现得自信、机智，通过刻苦努力发展自我。B.高趋高避型：这类学生被称为“过度努力者”。这类学生在获得成功的同时又要掩饰自已的努力，会出现一种“隐讳努力”的现象。C.低趋高避型：这类学生被称为“逃避失败者”，他们更看重逃避失败而非期望成功。不爱学习的背后隐藏着他们对失败的强烈恐惧。题干中学生“多一分浪费”即不追求高分，属于“低趋”，“60分万岁”即看重避免挂科，属于“高避”。√D.低趋低避型：这类学生被称为“失败接受者”。这类学生不奢望成功，对失败也没有羞耻和恐惧感，他们对成就表现得漠不关心，不接受任何有关能力的挑战。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 107}},
  {"id": "kc|edu-psych|xl-03|知识点八|2", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点八：自我价值理论", "no": 2, "q": "自我价值理论认为个人追求成功的内在动力是（　）", "opts": ["自我价值感", "需要的满足", "自己的兴趣", "适当的归因"], "a": 0, "exp": "此题考查自我价值理论。自我价值理论认为，人天生就有维护自尊和自我价值感的需要，个人追求成功的内在动力是自我价值感。例如，学生学习成功的内在动力就是保持积极的、有能力的自我形象。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 107}},
  {"id": "kc|edu-psych|xl-03|知识点八|3", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点八：自我价值理论", "no": 3, "q": "根据自我价值理论，小明在数学学习中存在明显防御心态：课上故意态度散漫，还时常向同学宣称“数学这门课根本不重要，学好学坏无所谓”。他属于（　）", "opts": ["高趋低避型", "高趋高避型", "低趋高避型", "低趋低避型"], "a": 2, "exp": "此题考查自我价值理论。A.高趋低避型的学生拥有无穷的好奇心，对学习有极高的卷人水平。B.高趋高避型的学生同时感受到成功的诱惑和对失败的恐惧。题干未体现出成功对小明的诱惑。C.低趋高避型的学生被称为“逃避失败者”。这类学生更看重逃避失败而非期望成功，防御心态、态度散漫的背后隐藏着他们对失败的强烈恐惧。面对没有把握成功的任务时，这种恐惧甚至让其必须采用逃避的手段，这种防御更多体现在心理层面，如尽量降低该任务的重要性，“认为数学不重要”。√D.低趋低避型的学生不奢望成功，对失败也没有羞耻和恐惧感，他们对成就表现得漠不关心，不接受任何有关能力的挑战。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 107}},
  {"id": "kc|edu-psych|xl-03|知识点九|1", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点九：综合题", "no": 1, "q": "以下学习动机理论中，不属于认知理论的是（　）", "opts": ["自由学习理论", "自我效能感", "成败归因理论", "自我价值理论"], "a": 0, "exp": "此题考查学习动机理论的分类。自由学习理论是人本主义学习动机理论的典型代表。此题为选非题，因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 107}},
  {"id": "kc|edu-psych|xl-03|知识点九|2", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点九：综合题", "no": 2, "q": "在对学习动机的作用做出解释时，既考虑行为的结果，又考虑个人信念等因素的影响的动机理论学派是（　）", "opts": ["行为主义学派", "认知主义学派", "社会（观察）学习理论学派", "人本主义学派"], "a": 2, "exp": "此题考查学习动机理论学派。社会（观察）学习理论学派的代表人物班杜拉在自我效能感理论中提到的结果期望和效能期望，融合了行为主义学派和认知主义学派的观点，它们既考虑行为的结果，又考虑个人信念等因素的影响。因此，答案选C。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 108}},
  {"id": "kc|edu-psych|xl-03|知识点九|3", "bank": "kc", "subj": "edu-psych", "ch": "xl-03", "chName": "第三章 学习动机", "sec": "知识点九：综合题", "no": 3, "q": "“任务本身具有较强的趣味性，不管任务完成水平如何，都预先提供物质化奖励，那对于内部动机的影响是致命的。”以上观点出自（　）", "opts": ["自我效能感理论：·", "成就动机理论", "成就目标理论", "自我决定理论"], "a": 3, "exp": "此题考查自我决定理论。自我决定理论在强调内部动机的同时，也关注外部动机是如何影响内部动机的。它认为外部动机使用不当会导致内部动机的抵消。因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 108}},
  {"id": "kc|edu-psych|xl-04|知识点一|1", "bank": "kc", "subj": "edu-psych", "ch": "xl-04", "chName": "第四章 知识的建构", "sec": "知识点一：知识的含义与分类", "no": 1, "q": "小刚利用改变物体接触面积大小或光滑程度的方法，来增强或减弱滑板的摩擦力。这主要说明小刚能够运用（　）", "opts": ["元认知知识", "描述性知识", "情境性知识", "程序性知识"], "a": 3, "exp": "此题考查知识的分类。A.元认知知识：对认知过程的知识和观念，包括有关个人作为学习者的知识、有关任务的知识、有关学习策略及其使用的知识。C.情境性知识：依赖特定情境的实践性知识。题干未强调具体情境（如天气、场地），小刚的方法是通用的操作方法。D.程序性知识：主要指“怎么做”的知识。题干中，小刚知道增强和减弱摩擦力的方法，“方法”是关于怎样做的知识，即程序性知识。√", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 109}},
  {"id": "kc|edu-psych|xl-04|知识点一|2", "bank": "kc", "subj": "edu-psych", "ch": "xl-04", "chName": "第四章 知识的建构", "sec": "知识点一：知识的含义与分类", "no": 2, "q": "某教师听完一场教学经验交流会后，很受启发，当他想把专家的教学方法运用到自己的教学中时，需要处理大量的（　）", "opts": ["陈述性知识", "程序性知识", "结构良好领域知识", "结构不良领域知识"], "a": 3, "exp": "此题考查知识的分类。A.陈述性知识：主要指“是什么”的知识。B.程序性知识：主要指“怎么做”的知识。C.结构良好领域知识：由明确的事实、概念和规则构成的结构化的知识。D.结构不良领域知识：有关被灵活应用的知识。题干中，教师想把专家的教学方法运用到自己的教学中，需要处理大量结构不良领域知识。√", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 109}},
  {"id": "kc|edu-psych|xl-04|知识点一|3", "bank": "kc", "subj": "edu-psych", "ch": "xl-04", "chName": "第四章 知识的建构", "sec": "知识点一：知识的含义与分类", "no": 3, "q": "以下属于陈述性知识的是（　）", "opts": ["景泰蓝制作过程的介绍", "玩具的说明书", "烹饪手册", "导游对景点的解说"], "a": 3, "exp": "此题考查陈述性知识。A、B、C选项均带有具体的操作步骤，涉及“怎么做”，属于程序性知识；而D选项反映事物的状态，导游解说主要描述的是“是什么”“怎么样”，属于陈述性知识。因此，答案选D。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 109}},
  {"id": "kc|edu-psych|xl-04|知识点一|4", "bank": "kc", "subj": "edu-psych", "ch": "xl-04", "chName": "第四章 知识的建构", "sec": "知识点一：知识的含义与分类", "no": 4, "q": "我们理解别人的思想和感情，这属于（　）", "opts": ["隐性知识社会化", "隐性知识外化", "显性知识内化", "显性知识综合化"], "a": 0, "exp": "此题考查知识的分类。A.通过隐性知识社会化，我们分享别人的经历和经验，理解别人的思想和情感。√B.通过隐性知识外化，我们用其他人能够理解的方式将隐性知识表达为显性知识。C.通过显性知识内化，我们将显性知识与自已的原有知识进行综合，转换成个人的隐性知识。D.通过显性知识综合化，我们将显性知识进行综合，转换成更复杂的显性知识。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 109}},
  {"id": "kc|edu-psych|xl-04|知识点一|5", "bank": "kc", "subj": "edu-psych", "ch": "xl-04", "chName": "第四章 知识的建构", "sec": "知识点一：知识的含义与分类", "no": 5, "q": "在知识的建构过程中，旧知识由于新知识的加入发生一定的调整和改组，这叫作（　）", "opts": ["知识的顺应", "产生式", "知识的同化", "知识的变革"], "a": 0, "exp": "此题考查知识建构的基本机制。A.知识的顺应：陈述性知识建构的基本机制，顺应意味着新旧知识之间的磨合、协调，体现了知识发展的对立性和改造性。符合题意。√B.产生式：程序性知识建构的基本机制，是指条件一动作的配对，即“如果某种条件满足，那么就执行某种动作”的知识。C.知识的同化：陈述性知识建构的基本机制，同化意味着学习者联系、利用原有知识来获取新概念，它体现了知识发展的连续性和累积性。D.知识的变革：干扰选项，不属于知识建构的基本机制。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 109}},
  {"id": "kc|edu-psych|xl-04|知识点一|6", "bank": "kc", "subj": "edu-psych", "ch": "xl-04", "chName": "第四章 知识的建构", "sec": "知识点一：知识的含义与分类", "no": 6, "q": "对于陈述性知识建构的机制，下列说法不正确的是（　）", "opts": ["陈述性知识的建构是通过新旧知识的同化和顺应来实现的", "同化意味着新旧知识的对立性和改造性，顺应意味着新旧知识的连续性和累积性", "同化和顺应是对立统一的", "真正的同化离不开顺应的发生"], "a": 1, "exp": "此题考查知识建构的基本机制。B选项中，顺应意味着新旧知识的对立性和改造性，同化意味着新旧知识的连续性和累积性。此题为选非题，因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 109}},
  {"id": "kc|edu-psych|xl-04|知识点二|1", "bank": "kc", "subj": "edu-psych", "ch": "xl-04", "chName": "第四章 知识的建构", "sec": "知识点二：知识的理解", "no": 1, "q": "在奥苏伯尔的有意义学习理论中，学生把苹果、香蕉、草莓都称为水果。这属于（　）", "opts": ["信号学习", "表征学习", "命题学习", "概念学习"], "a": 3, "exp": "此题考查知识理解的类型。A.信号学习：个体学习对某种信号做出某种反应，不属于奥苏伯尔区分的有意义学习的三种类型。B.表征学习：学习单个符号或一组符号的意义，或者说学习它们代表什么。C.命题学习：掌握概念或事物之间的关系。命题是以句子的形式表达的，可分为非概括性命题和概括性命题两类。D.概念学习：掌握以符号代表的同类事物共同的本质特征。题干中，学生将苹果、香蕉、草莓都称为水果，认识到了它们的共同特征，属于概念学习。√", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 109}},
  {"id": "kc|edu-psych|xl-04|知识点二|2", "bank": "kc", "subj": "edu-psych", "ch": "xl-04", "chName": "第四章 知识的建构", "sec": "知识点二：知识的理解", "no": 2, "q": "通过课堂学习，小学生了解了“长方形”具有一系列属性，包括有四条边、对边相等且平行，是一个平面封闭图形。此时，小学生关于长方形的知识的表征形式是（　）", "opts": ["图式", "命题", "表象", "概念"], "a": 3, "exp": "此题考查知识的表征方式。A.图式：有组织的知识结构，即关于某个主题的一个知识单元，包括与该主题相关的一套相互联系的基本概念，构成了感知、理解外界信息的框架结构。B.命题：概念或事物之间的关系，以句子的形式表达。C.表象：人们头脑中形成的与现实世界的情境相类似的心理图像。D.概念：代表着事物的基本属性和基本特征，是一种简单的表征形式。题干中小学生了解“长方形”的基本属性和基本特征，是通过概念这一表征形式。√", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 109}},
  {"id": "kc|edu-psych|xl-04|知识点二|3", "bank": "kc", "subj": "edu-psych", "ch": "xl-04", "chName": "第四章 知识的建构", "sec": "知识点二：知识的理解", "no": 3, "q": "小明在上课的时候听到教师说“蜻蜓是益虫”，回家后他对父母说“蜻蜓是人类的好朋友”，此时小明对于“蜻蜓是益虫”的表征形式是（　）", "opts": ["图式", "命题", "表象", "概念"], "a": 1, "exp": "此题考查知识的表征方式。命题是意义观念的最小单元，用于表述一个事实或描述一个状态。命题是用句子表达的，但命题不等于句子，命题代表观念本身，同一命题可以用不同的句子表达。“蜻蜓是益虫”在表征形式上是一个命题。因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 109}},
  {"id": "kc|edu-psych|xl-04|知识点二|4", "bank": "kc", "subj": "edu-psych", "ch": "xl-04", "chName": "第四章 知识的建构", "sec": "知识点二：知识的理解", "no": 4, "q": "现套课程公众号【研大]下图所示是一个幼儿园儿童关于“午饭”的脚本。该图片中呈现的知识的表征方式是（首先你在户外玩一会儿当教师叫你的名字时走进来拿到你的饭盆后坐下开始吃饭把剩饭倒掉准备午休（　）", "opts": ["命题网络", "表象", "图式", "产生式"], "a": 2, "exp": "此题考查知识的表征方式。我们头脑中储存着多种不同类型的图式，如物体图式（杯子的图式）事件图式（脚本）动作图式（骑自行车的图式）等。题干中的图呈现的是脚本，即各事件发生的过程及其各过程间的相互关系的图式。因此，答案选C。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 109}},
  {"id": "kc|edu-psych|xl-04|知识点二|5", "bank": "kc", "subj": "edu-psych", "ch": "xl-04", "chName": "第四章 知识的建构", "sec": "知识点二：知识的理解", "no": 5, "q": "某教师在讲解“分数的意义”时，先通过把一块蛋糕平均分成几份以引人分数的概念，然后在课堂练习中用一张长方形纸对折、再对折来表示不同分数，最后在课后作业中设计了用分数表示一个班级中男生、女生人数关系的问题。该教师使用的概念学习的策略是（　）", "opts": ["提供反例", "组织合作探究", "提供变式", "创设游戏情境"], "a": 2, "exp": "此题考查概念教学的策略。该教师通过不同情境（蛋糕、长方形纸、班级人数）和不同表征方式（实物、图形、数量关系）来呈现分数的概念，帮助学生从多角度理解分数的本质，这是“提供变式”策略的典型运用，有助于学生把握概念的关键属性，避免理解僵化。因此，答案选C。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 110}},
  {"id": "kc|edu-psych|xl-04|知识点二|6", "bank": "kc", "subj": "edu-psych", "ch": "xl-04", "chName": "第四章 知识的建构", "sec": "知识点二：知识的理解", "no": 6, "q": "在学习“金属”这一概念时，小张认为“所有金属都能被磁铁吸引”，于是判断铜属于非金属。这一错误判断最有可能的原因是（　）", "opts": ["出现了过度概括", "受到日常经验的误导", "使用了概念的反例", "出现了概括不足"], "a": 0, "exp": "此题考查概念教学的策略。的普遍属性，导致对非磁性金属（如铜、铝）的分类判断错误，这是“过度概括”现象的典型表现。因此，答案选A。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 110}},
  {"id": "kc|edu-psych|xl-04|知识点二|7", "bank": "kc", "subj": "edu-psych", "ch": "xl-04", "chName": "第四章 知识的建构", "sec": "知识点二：知识的理解", "no": 7, "q": "学生更容易理解“水”“植物的花”“植物的根”等，但不容易理解“化学键”“分子式”等，这个例子中，影响知识理解的因素是（　）", "opts": ["学习材料的意义性", "学习材料内容的具体程度", "学习材料的相对复杂性", "学习材料的难度"], "a": 1, "exp": "此题考查影响知识理解的因素。“水”“植物的花”“植物的根”对学生来讲是具体的、形象的，容易激活学生的先前经验。“化学键”“分子式”属于抽象的、概括化的、远离具体经验的内容，学生需要用更多的意识努力，去分析、思考这些内容，生成与原有知识经验的联系。这个例子中，影响知识理解的因素是学习材料内容的具体程度。因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 110}},
  {"id": "kc|edu-psych|xl-04|知识点三|1", "bank": "kc", "subj": "edu-psych", "ch": "xl-04", "chName": "第四章 知识的建构", "sec": "知识点三：知识的整合与深化", "no": 1, "q": "有些学生在考试时，由于紧张，之前已经记住的知识怎么也想不起来。心理学中对这种现象进行解释的理论是（　）", "opts": ["痕迹衰退说", "材料干扰说", "检索困难说", "动机性遗忘说"], "a": 3, "exp": "此题考查遗忘的原因。A.痕迹衰退说：人们在学习时神经活动引起大脑产生某种变化，并留下各种记忆痕迹，这些记忆痕迹会随着时间的延长而逐渐衰退。B.材料干扰说：遗忘的发生是由于人们在一种学习任务结束之后又去从事其他的学习任务。C.检索困难说：人们一时无法回忆起所需要的信息，并不是遗忘之故，而是因为难以找到其提取的线索。D.动机性遗忘说：强调个体的需要、欲望、动机、情绪等心理因素在记忆中的作用。紧张导致已经记住的知识想不起来，是受到了个体情绪的影响。√", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 110}},
  {"id": "kc|edu-psych|xl-04|知识点三|2", "bank": "kc", "subj": "edu-psych", "ch": "xl-04", "chName": "第四章 知识的建构", "sec": "知识点三：知识的整合与深化", "no": 2, "q": "见到多年未见的老同学，明明感觉知道对方的名字却想不起来，但当别人提到他曾经的班级或共同的朋友时，才突然想起他的名字。这种现象体现了遗忘理论中的（　）", "opts": ["痕迹衰退说", "材料干扰说", "检索困难说", "动机性遗忘说"], "a": 2, "exp": "此题考查遗忘的原因。A.痕迹衰退说：遗忘是由于记忆痕迹得不到强化而逐渐衰退。B.材料干扰说：强调新旧知识之间的相互干扰导致遗忘。C.检索困难说：遗忘是由于失去了提取线索或线索错误。题干中，一开始想不起来老同学的名字是因为失去了直接提取名字的线索，而当别人提到他曾经的班级或共同的朋友这些相关线索时，就能够回忆起来，这正体现了检索困难说。√D.动机性遗忘说：遗忘是由情绪或动机的压抑引起的。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 110}},
  {"id": "kc|edu-psych|xl-04|知识点四|1", "bank": "kc", "subj": "edu-psych", "ch": "xl-04", "chName": "第四章 知识的建构", "sec": "知识点四：知识的应用与迁移", "no": 1, "q": "根据迁移内容的抽象和概括水平，可将迁移划分为（　）", "opts": ["水平迁移和垂直迁移", "正迁移和负迁移", "一般迁移和具体迁移", "顺向迁移和逆向迁移"], "a": 0, "exp": "此题考查迁移的类型。A.水平迁移和垂直迁移：划分依据是迁移内容的抽象和概括水平。√B.正迁移和负迁移：划分依据是迁移的影响效果。C.一般迁移和具体迁移：划分依据是迁移发生的方式和范围。D.顺向迁移和逆向迁移：划分依据是迁移的方向。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 110}},
  {"id": "kc|edu-psych|xl-04|知识点四|2", "bank": "kc", "subj": "edu-psych", "ch": "xl-04", "chName": "第四章 知识的建构", "sec": "知识点四：知识的应用与迁移", "no": 2, "q": "根据布鲁纳的迁移分类法，原理和态度的迁移属于（　）", "opts": ["特殊迁移", "一般迁移", "顺向迁移", "逆向迁移"], "a": 1, "exp": "此题考查迁移的类型。A.特殊迁移：某一领域的学习直接对学习另一领域所产生的影响。B.一般迁移：一般原理、方法、策略、态度的迁移。√C.顺向迁移：前面学习对后面学习的影响。D.逆向迁移：后面学习对前面学习的影响。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 111}},
  {"id": "kc|edu-psych|xl-04|知识点四|3", "bank": "kc", "subj": "edu-psych", "ch": "xl-04", "chName": "第四章 知识的建构", "sec": "知识点四：知识的应用与迁移", "no": 3, "q": "小明的母亲让小明上午学习汉语拼音，晚上学习英文字母，结果小明经常混淆二者的发音，这一学习现象属于（　）", "opts": ["正迁移", "负迁移", "顺迁移", "逆迁移"], "a": 1, "exp": "此题考查迁移的类型。正迁移是一种学习对另外一种学习的“积极影响”，负迁移是一种学习对另外一种学习的“消极影响”。学习汉语拼音对学习英文字母产生了消极影响，即负迁移。由于两种学习在时间上交错进行，干扰是相互的，不必区分顺、逆迁移，因为题干强调的是混淆的结果（干扰），而非方向。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 111}},
  {"id": "kc|edu-psych|xl-04|知识点四|4", "bank": "kc", "subj": "edu-psych", "ch": "xl-04", "chName": "第四章 知识的建构", "sec": "知识点四：知识的应用与迁移", "no": 4, "q": "由于小明会打羽毛球，很快就学会了打网球。这种现象为（　）", "opts": ["顺向正迁移", "逆向正迁移", "顺向负迁移", "逆向负迁移"], "a": 0, "exp": "此题考查迁移的类型。小明之前打羽毛球的基础对之后的网球学习产生了积极的影响，属于顺向正迁移。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 111}},
  {"id": "kc|edu-psych|xl-04|知识点四|5", "bank": "kc", "subj": "edu-psych", "ch": "xl-04", "chName": "第四章 知识的建构", "sec": "知识点四：知识的应用与迁移", "no": 5, "q": "小强利用数学课上所学的知识设计校报的版式。从迁移发生的自动化程度来看，这种迁移属于（　）", "opts": ["顺向迁移", "特殊迁移", "低通路迁移", "高通路迁移"], "a": 3, "exp": "此题考查迁移的类型。从迁移发生的自动化程度来看，迁移分为低通路迁移与高通路迁移。高通路迁移指有意识地将在某一情境下习得的抽象知识运用到新的情境中。题干中，小强利用数学课上所学的知识去做板报设计属于高通路迁移。因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 111}},
  {"id": "kc|edu-psych|xl-04|知识点四|6", "bank": "kc", "subj": "edu-psych", "ch": "xl-04", "chName": "第四章 知识的建构", "sec": "知识点四：知识的应用与迁移", "no": 6, "q": "学会了用铅笔写字，自然而然就会用钢笔写字，这属于（　）", "opts": ["负迁移", "远迁移", "低通路迁移", "高通路迁移"], "a": 2, "exp": "此题考查迁移的类型。A.负迁移：一种学习对另一种学习的消极影响，包括一种学习所形成的心理状态，如反应定势。该选项与题意不符。B.远迁移：个体将所学的经验迁移到与原学习情境极不相似的其他情境中。该选项与题意不符。C.低通路迁移：反复练习的技能自动化的迁移，如驾驶不同的汽车、用不同的笔写字就属于低通路迁移。另外，题干中的自然而然也体现了自动化迁移。√D.高通路迁移：有意识地将在某一情境中习得的抽象知识运用到新的情境中，如利用做笔记策略来阅读文章。该选项与题意不符。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 111}},
  {"id": "kc|edu-psych|xl-04|知识点四|7", "bank": "kc", "subj": "edu-psych", "ch": "xl-04", "chName": "第四章 知识的建构", "sec": "知识点四：知识的应用与迁移", "no": 7, "q": "举一反三、闻一知十、触类旁通属于哪种迁移？（　）", "opts": ["同化迁移", "顺应迁移", "重组迁移", "逆向迁移"], "a": 0, "exp": "此题考查迁移的类型。（1）举一反三：从一个事例推知同类其他事例，本质是同类知识的直接应用。（2）闻一知十：听到一点就能推知很多，体现对同类知识的概括性理解。（3）触类旁通：通过接触一类事物推知同类其他事物，依赖已有认知结构的类属扩展。A.同化迁移：自上而下的迁移。题干中的成语均体现了将原有的认知经验（同属某一概念或原理）应用到本质特征相同的一类事物中去，符合同化迁移的特征。√B.顺应迁移：自下而上的迁移，指将原有的认知经验应用于新情境时，需要调整原有的经验才能解决新问题。C.重组迁移：重新组合原有的经验中的构成要素或成分，调整各成分之间的关系或建立新的联系，并将其应用于新的情境。D.逆向迁移：后面学习对前面学习的影响。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 111}},
  {"id": "kc|edu-psych|xl-04|知识点四|8", "bank": "kc", "subj": "edu-psych", "ch": "xl-04", "chName": "第四章 知识的建构", "sec": "知识点四：知识的应用与迁移", "no": 8, "q": "树林。在学习“森”字时，学生能明白它是由三个“木”字组成的，代表森林，是树木更加繁茂的意思。这里所产生的迁移属于（　）", "opts": ["横向迁移", "低通路迁移", "一般迁移", "特殊迁移"], "a": 3, "exp": "此题考查迁移的类型。A.横向迁移：同一难度水平的迁移，如理解了凹透镜的原理，就能理解凸透镜的原理。题干中，学生对汉字构字规则（会意字）的理解逐步深化，从“木”到“林”再到“森”，属于同一领域内由简单到复杂的递进式学习，这是纵向迁移的体现。B.低通路迁移：反复练习的技能自动化的迁移。C.一般迁移：迁移产生的原因不明确，既可能是原理、原则的迁移，也可能是态度的迁移。D.特殊迁移：某一领域或课题的学习直接对学习另一领域或课题所产生的影响。题干中，学生通过已深联系微信1931637888", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 111}},
  {"id": "kc|edu-psych|xl-04|知识点四|9", "bank": "kc", "subj": "edu-psych", "ch": "xl-04", "chName": "第四章 知识的建构", "sec": "知识点四：知识的应用与迁移", "no": 9, "q": "贾德证明学习迁移的概括化理论的实验是（　）", "opts": ["迷宫实验", "小鸡啄米实验", "水中打靶实验", "迷笼实验"], "a": 2, "exp": "此题考查概括化理论。贾德通过著名的水下打靶实验提出了概括化理论。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 111}},
  {"id": "kc|edu-psych|xl-04|知识点四|10", "bank": "kc", "subj": "edu-psych", "ch": "xl-04", "chName": "第四章 知识的建构", "sec": "知识点四：知识的应用与迁移", "no": 10, "q": "强调前后学习的情境相似性对迁移效果影响的理论是（　）", "opts": ["概括化理论", "相同元素说", "关系理论", "认知结构迁移理论"], "a": 1, "exp": "此题考查早期的迁移理论。A.概括化理论：迁移产生的关键在于学习者能够概括出两组活动之间的共同原理。B：相同元素说：迁移的程度取决于两种情境的相同要素有多少。符合题意。√C.关系理论：重视学习者对学习情境内部关系的顿悟在迁移中的作用。D.认知结构迁移理论：重视认知结构本身的可利用性、可辨别性和清晰稳定性在迁移中的作用。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 111}},
  {"id": "kc|edu-psych|xl-04|知识点四|11", "bank": "kc", "subj": "edu-psych", "ch": "xl-04", "chName": "第四章 知识的建构", "sec": "知识点四：知识的应用与迁移", "no": 11, "q": "小学语文教材第一册识字《日月明》一课中这样表述：“日月明，鱼羊鲜，小土尘，小大尖。”该教学策略运用的迁移理论是（　）", "opts": ["形式训练说", "相同元素说", "概括化理论", "关系理论"], "a": 1, "exp": "此题考查迁移理论。A.形式训练说：人的心智是由各种官能组成的，这些官能可以像肌肉一样通过训练得到发展和加强。B.相同元素说：迁移的程度取决于两种情境的相同要素有多少。题干中的识字课是引导学生分析已学过的简单汉字（“日”和“月”）与新学习材料（“明”）之间的关系，通过把二者之间的共同要素进行迁移，使学生掌握更多的汉字。√C.概括化理论：迁移产生的关键在于学习者能够概括出两组活动之间的共同原理。D.关系理论：重视学习者对学习情境内部关系的顿悟在迁移中的作用。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 111}},
  {"id": "kc|edu-psych|xl-05|知识点一|1", "bank": "kc", "subj": "edu-psych", "ch": "xl-05", "chName": "第五章 技能的形成", "sec": "知识点一：技能及其特点", "no": 1, "q": "下列对技能的描述，正确的是（　）", "opts": ["技能就是活动程序", "技能就是潜能", "技能是通过练习提高的", "技能一下子就能学会"], "a": 2, "exp": "此题考查技能的含义。技能是指通过练习形成的合乎法则或程序的身体或认知活动方式，具有以下特点：（1）技能要通过练习而形成，不是本能，也不是潜能，更不是一下子就能学会的；（2）技能是合乎法则或程序的活动方式，区别于随意行为；（3）技能是身体或认知活动方式，不是活动程序，技能的掌握不是通过言语表述，而是通过实际的动作活动表现出来的。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 112}},
  {"id": "kc|edu-psych|xl-05|知识点一|2", "bank": "kc", "subj": "edu-psych", "ch": "xl-05", "chName": "第五章 技能的形成", "sec": "知识点一：技能及其特点", "no": 2, "q": "下列选项中，不是技能的是（　）", "opts": ["走路", "骑自行车", "做梦", "制订计划"], "a": 2, "exp": "此题考查技能的含义。技能是通过练习形成的合乎规则或程序的身体或认知活动方式。A、B、D选项均是需要练习才会获得的活动方式，且具有一定的规则性。C选项做梦属于本能。此题为选非题，因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 112}},
  {"id": "kc|edu-psych|xl-05|知识点一|3", "bank": "kc", "subj": "edu-psych", "ch": "xl-05", "chName": "第五章 技能的形成", "sec": "知识点一：技能及其特点", "no": 3, "q": "下列对心智技能的特点的描述，不正确的是（　）", "opts": ["客观性A观念性动作技能必须是合乎法则和程序的身体活动方式，无论是在动作的力量、速度、幅度，还是结构等方面都要有标准可循，体现了动作技能的（", "内潜性精确性", "简缩性协调性）", "不可重复性适应性"], "a": 1, "exp": "．理解题此题考查动作技能的特点。A.客观性：侧重动作技能是客观存在的身体活动，依托于身体运动器官的实际操作，而非主观的思维活动，与“标准、法则”无关，排除。B.精确性：题干强调的是动作的控制要符合规范，要求动作执行时在力量、速度、幅度等方面按标准做到准确，这体现了动作技能的精确性（如投篮、射击等要求动作的精确性）。√C.协调性：强调动作各环节、身体各部位之间的配合与同步（如手眼协调、四肢协调），侧重“配合度”而非“标准化”，排除。D.适应性：动作技能能根据不同的情境、条件进行适当调整，以顺利完成任务（如不同场地打球时调整动作），侧重“灵活性”而非“遵循标准”，排除。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 112}},
  {"id": "kc|edu-psych|xl-05|知识点一|4", "bank": "kc", "subj": "edu-psych", "ch": "xl-05", "chName": "第五章 技能的形成", "sec": "知识点一：技能及其特点", "no": 4, "q": "对于操作技能和心智技能的区别，以下表述不正确的是（　）", "opts": ["操作技能的对象是具体的物质实体，心智技能的对象是观念性的", "操作技能的执行过程是外显的，心智技能的执行过程是内潜性的", "操作技能的动作可以合并，心智技能的动作则不能合并", "操作技能的动作不能合并，必须切实执行，心智技能的动作可以合并"], "a": 2, "exp": "此题考查操作技能和心智技能的区别与联系。C选项中，操作技能是系列动作的连锁，因而其动作结构必须从实际出发，符合实际，不能省略；而心智技能是借助于内部言语实现的，可以高度省略、高度简缩。此题为选非题，因此，答案选C。深联系微信1931637日8日", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 112}},
  {"id": "kc|edu-psych|xl-05|知识点二|1", "bank": "kc", "subj": "edu-psych", "ch": "xl-05", "chName": "第五章 技能的形成", "sec": "知识点二：心智技能", "no": 1, "q": "下列选项中，（）不属于心智技能。（　）", "opts": ["书写技能", "阅读技能", "写作技能", "心算技能"], "a": 0, "exp": "此题考查心智技能。（1）心智技能也称智力技能、智慧技能，指借助于内部言语在人脑中进行的认知活动方式，如默读、心算、写作、观察、分析等。因此，阅读技能、写作技能、心算技能都属于心智技能。（2）操作技能也称运动技能、动作技能，指由一系列外部动作以合理的程序组成的操作活动方式，如骑车、做体操、书写等。因此，书写技能不属于心智技能。此题为选非题，因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 112}},
  {"id": "kc|edu-psych|xl-05|知识点二|2", "bank": "kc", "subj": "edu-psych", "ch": "xl-05", "chName": "第五章 技能的形成", "sec": "知识点二：心智技能", "no": 2, "q": "将一篇在电脑上写好的文章按一定格式排版所属的技能是（　）", "opts": ["动作技能", "心智技能", "言语信息", "态度"], "a": 1, "exp": "此题考查心智技能。A.动作技能：一系列外部动作以合理的程序组成的操作活动方式。动作技能强调外部动作，“按一定格式排版”更强调认知规划，而非外部动作。B.心智技能：借助于内部言语在人脑中进行的认知活动方式。对文章按格式排版时，需要先在头脑中规划排版逻辑（字体、行距、层级、版式等），再通过操作电脑落实，核心是大脑的设计、判断和调控过程，外部动作（敲击键盘、移动鼠标）只是辅助。√C.言语信息：有关事物的名称、时间、地点、定义以及特征等方面的事实性信息，属于“知道是什么”，而排版是“知道怎么做”的技能。D.态度：对人、事和物采取行动的内部状态，属于情感与行为倾向范畴，而非具体的技能。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 112}},
  {"id": "kc|edu-psych|xl-05|知识点二|3", "bank": "kc", "subj": "edu-psych", "ch": "xl-05", "chName": "第五章 技能的形成", "sec": "知识点二：心智技能", "no": 3, "q": "下列属于常见的心智技能的是（　）", "opts": ["驾驶汽车", "洗衣服", "打字", "解应用题"], "a": 3, "exp": "此题考查心智技能。A.驾驶汽车：核心是外部的程序化身体操作，属于动作技能。B.洗衣服：无论是手洗还是机洗，核心都是身体的操作动作，属于动作技能。C.打字：主要是肌肉骨骼的动作，虽然这种动作也受到人的思维的调节支配，但它属于动作技能。D.解应用题：核心是头脑中的认知加工过程，身体的书写、计算动作仅为辅助，属于心智技能。√", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 112}},
  {"id": "kc|edu-psych|xl-05|知识点二|4", "bank": "kc", "subj": "edu-psych", "ch": "xl-05", "chName": "第五章 技能的形成", "sec": "知识点二：心智技能", "no": 4, "q": "以下技能中，属于专门心智技能的是（　）", "opts": ["观察", "分析", "比较", "心算"], "a": 3, "exp": "此题考查心智技能。根据适用的范围不同，可以把心智技能分为专门心智技能和一般心智技能。（1）专门心智技能是进行某种专门的认知活动所必需的，也是在相应的专门智力活动中形成、发展和体现出来的。例如，默读与心算等技能是学生在学习活动中必须掌握的最基本的专门心智技能。（2）一般心智技能是指可以广泛应用于许多领域的心智技能，是在多种专门心智技能的基础上通过概括化形成发展起来的，如观察技能、分析技能、综合技能和比较技能等。因此，答案选D。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 112}},
  {"id": "kc|edu-psych|xl-05|知识点二|5", "bank": "kc", "subj": "edu-psych", "ch": "xl-05", "chName": "第五章 技能的形成", "sec": "知识点二：心智技能", "no": 5, "q": "根据冯忠良的三阶段模型，心智技能培养的第一步是（　）", "opts": ["原型操作", "原型定向", "原型内化", "原型反思"], "a": 1, "exp": "此题考查心智技能的形成过程。冯忠良根据有关研究并结合教学实际，提出心智技能形成三阶段说：原型定向、原型操作、原型内化。因此，原型定向是心智技能培养的第一步。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 113}},
  {"id": "kc|edu-psych|xl-05|知识点二|6", "bank": "kc", "subj": "edu-psych", "ch": "xl-05", "chName": "第五章 技能的形成", "sec": "知识点二：心智技能", "no": 6, "q": "31x43×3在教异分母分数加法？”时，教师先将计算过程逐步展开：3×44x34+9.13这说明此时学生的心智技能处于的形成阶段是（　）", "opts": ["活动定向阶段", "物质活动或物质化活动阶段", "有声的言语活动阶段", "无声的外部言语活动阶段"], "a": 1, "exp": "此题考查心智技能的形成过程。加里培林将心智技能的形成划分成五个阶段：（1）活动定向阶段：让学生在头脑中形成对活动程序和活动结果的映象。（2）物质活动或物质化活动阶段：运用实物或者模型、示意图等进行教学的阶段。这一阶段，教师要将动作展开，让学生实际完成每个动作。题干中教师将计算过程展开，是为了让学生跟着教师的步骤学会计算过程，符合该阶段的特点。（3）有声的言语活动阶段：不直接依赖实物或模拟品，而是借助出声的外部言语活动来完成各个操作步骤。（4）无声的外部言语活动阶段：以词的声音表象、动觉表象为中介而进行的智力活动。（5）内部言语活动阶段：凭借简化了的内部言语，似乎不需要多少意识的参与就能自动化进行的智力活动。因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 113}},
  {"id": "kc|edu-psych|xl-05|知识点三|1", "bank": "kc", "subj": "edu-psych", "ch": "xl-05", "chName": "第五章 技能的形成", "sec": "知识点三：操作技能", "no": 1, "q": "下列选项中，属于运动技能的是（　）", "opts": ["摇头", "系鞋带", "心算", "作文"], "a": 1, "exp": "此题考查对运动技能的理解。A选项摇头不属于技能，属于本能动作。C、D选项属于心智技能。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 113}},
  {"id": "kc|edu-psych|xl-05|知识点三|2", "bank": "kc", "subj": "edu-psych", "ch": "xl-05", "chName": "第五章 技能的形成", "sec": "知识点三：操作技能", "no": 2, "q": "以下选项中，属于连续性操作技能的是（　）", "opts": ["射击", "溜冰", "下棋", "举重"], "a": 1, "exp": "此题考查操作技能的主要类型。按照操作连续性的不同，可将操作技能分为连贯技能和不连贯技能。（1）连贯技能（连续性操作技能）：以连续、不间断的方式完成一系列动作（如说话、打字、唱歌等），动作之间没有明显的可以直接感觉出来的起点和终点，一般持续时间较长，需要根据实际情境对任务进行不断调整。B选项溜冰是连续的一系列动作，且无明显的起点和终点，持续时间较长，属于连续性操作技能。（2）不连贯技能（断续性操作技能）：对特定的外部刺激做出特定的不连续的运动，具有可以直接感知的起点和终点。完成这种技能的时间相对较短（如挪动棋子、倒水等）。A、C、D选项都有可以直接感知的起点和终点，且完成这些技能的时间相对较短，属于不连贯技能。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 113}},
  {"id": "kc|edu-psych|xl-05|知识点三|3", "bank": "kc", "subj": "edu-psych", "ch": "xl-05", "chName": "第五章 技能的形成", "sec": "知识点三：操作技能", "no": 3, "q": "下列动作技能中，不属于连贯技能的是（　）", "opts": ["打字", "说话", "倒水", "唱歌"], "a": 2, "exp": "此题考查操作技能的主要类型。依据知识点三第2题解析可知，A、B、D选项属于连贯技能，C选项倒水属于不连贯技能。此题为选非题，因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 113}},
  {"id": "kc|edu-psych|xl-05|知识点三|4", "bank": "kc", "subj": "edu-psych", "ch": "xl-05", "chName": "第五章 技能的形成", "sec": "知识点三：操作技能", "no": 4, "q": "以下属于断续性操作技能的是（　）", "opts": ["游泳", "滑雪", "开车", "射箭"], "a": 3, "exp": "此题考查操作技能的主要类型。依据知识点三第2题解析可知，A、B、C选项的动作属于连续性操作技能，D选项射箭属于断续性操作技能。因此，答案选D。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 113}},
  {"id": "kc|edu-psych|xl-05|知识点三|5", "bank": "kc", "subj": "edu-psych", "ch": "xl-05", "chName": "第五章 技能的形成", "sec": "知识点三：操作技能", "no": 5, "q": "以下属于开放性操作技能的是（　）", "opts": ["踢足球", "舞蹈", "体操", "气功"], "a": 0, "exp": "A理解题此题考查操作技能的主要类型。按照动作对环境依赖程度的不同，可将操作技能分为封闭性技能和开放性技能。（1）封闭性技能：一种完全依赖内部肌肉反馈作为刺激指导的技能，这种技能闭着眼晴也能完成，如在黑板上徒手快速画一个大圆就接近于封闭性技能。舞蹈、体操、气功主要依赖内部肌肉反馈进行活动，属于封闭性技能。（2）开放性技能：主要依赖于周围环境提供的信息，正确地感知周围环境成为运动调节的重要因素，要求人们具有处理外界信息变化的能力和对事件发生的预见能力。踢足球时赛场中对手的走位、传球的时机等都是实时变化、不可预测的，球员的动作必须根据实际情境进行动态调整，无法按照固定流程完成，属于开放性技能。因此，答案选A。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 113}},
  {"id": "kc|edu-psych|xl-05|知识点三|6", "bank": "kc", "subj": "edu-psych", "ch": "xl-05", "chName": "第五章 技能的形成", "sec": "知识点三：操作技能", "no": 6, "q": "“在黑板上徒手快速画一个大圆”属于（　）", "opts": ["封闭性技能", "开放性技能", "连贯技能", "粗大技能"], "a": 0, "exp": "此题考查操作技能的主要类型。依据知识点三第5题解析可知，“在黑板上徒手快速画一个大圆”属于封闭性技能。因此，答案选A。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 113}},
  {"id": "kc|edu-psych|xl-05|知识点三|7", "bank": "kc", "subj": "edu-psych", "ch": "xl-05", "chName": "第五章 技能的形成", "sec": "知识点三：操作技能", "no": 7, "q": "以下属于封闭性操作技能的是（　）", "opts": ["打网球", "踢足球", "游泳", "打乒乓球"], "a": 2, "exp": "此题考查操作技能的主要类型。依据知识点三第5题解析可知，A、B、D选项属于开放性操作技能。C选项游泳属于封闭性操作技能。深联系微信1931637日8日因此，答案选C。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 113}},
  {"id": "kc|edu-psych|xl-05|知识点三|8", "bank": "kc", "subj": "edu-psych", "ch": "xl-05", "chName": "第五章 技能的形成", "sec": "知识点三：操作技能", "no": 8, "q": "以下属于徒手性操作技能的是（　）", "opts": ["跳芭蕾舞", "骑自行车", "击剑", "溜冰"], "a": 0, "exp": "A理解题此题考查操作技能的主要类型。按操作对象的不同，可将操作技能分为徒手性操作技能和器械性操作技能。（1）徒手性操作技能即无须器械，仅通过身体协调来完成的操作技能。A选项跳芭蕾舞属于徒手性操作技能。（2）器械性操作技能主要是通过操纵一定的器械来进行的。B、C、D选项均需要通过一定的器械来完成，属于器械性操作技能。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 113}},
  {"id": "kc|edu-psych|xl-05|知识点三|9", "bank": "kc", "subj": "edu-psych", "ch": "xl-05", "chName": "第五章 技能的形成", "sec": "知识点三：操作技能", "no": 9, "q": "以下属于器械性操作技能的是（　）", "opts": ["弹琴", "跑步", "跳舞", "跳远"], "a": 0, "exp": "此题考查操作技能的主要类型。依据知识点三第8题解析可知，B、C、D选项均无须器械即可完成，是徒手性操作技能。弹琴需借助乐器来完成。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 113}},
  {"id": "kc|edu-psych|xl-05|知识点三|10", "bank": "kc", "subj": "edu-psych", "ch": "xl-05", "chName": "第五章 技能的形成", "sec": "知识点三：操作技能", "no": 10, "q": "运动技能的表征方式是（　）", "opts": ["命题", "语义网络", "命题网络", "产生式系统"], "a": 3, "exp": "此题考查运动技能的表征方式。A.命题：陈述性知识的表征方式。B.语义网络：陈述性知识的表征方式。C.命题网络：陈述性知识的表征方式。D.产生式系统：程序性知识的表征方式。运动技能的形成需要先掌握程序性知识，再通过实际操作将程序性知识转化为外显的动作。√", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 113}},
  {"id": "kc|edu-psych|xl-05|知识点四|1", "bank": "kc", "subj": "edu-psych", "ch": "xl-05", "chName": "第五章 技能的形成", "sec": "知识点四：操作技能的形成过程", "no": 1, "q": "小张刚开始学习打篮球时，需要盯着球才能完成运球动作。经过一段时间的练习，他逐渐能够不用看球，仅凭手部肌肉感觉就可以来回运球。根据菲茨与波斯纳的操作技能形成的三阶段模型，此时小张的视觉控制与动觉控制发生的变化是（　）", "opts": ["始终以视觉控制为主", "始终以动觉控制为主", "动觉控制渐弱，视觉控制渐强", "视觉控制渐弱，动觉控制渐强"], "a": 3, "exp": "此题考查菲茨与波斯纳的三阶段模型。菲茨与波斯纳将操作技能的形成分为三个阶段：（1）认知阶段：依赖视觉观察和语言指导（如初学运球时紧盯球）。（2）联系阶段：动作合并为“组块”，视觉控制减弱，动觉（肌肉感觉）控制增强（如运球时不看球）。（3）自动化阶段：动作完全流畅，无须意识控制。因此，答案选D。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 113}},
  {"id": "kc|edu-psych|xl-05|知识点四|2", "bank": "kc", "subj": "edu-psych", "ch": "xl-05", "chName": "第五章 技能的形成", "sec": "知识点四：操作技能的形成过程", "no": 2, "q": "冯忠良把操作技能的形成过程分为（　）阶段。（　）", "opts": ["定向一练习—巩固—确定", "调整—定向—确定一应用", "定向一模仿一整合一熟练", "模仿—调整熟练一应用"], "a": 2, "exp": "此题考查冯忠良的四阶段模型。冯忠良认为操作技能的形成过程可以分为四个阶段：（1）操作的定向阶段：个体了解操作活动的结构与要求，在头脑中建立起操作活动的定向映象的过程。（2）操作的模仿阶段：个体将其在操作的定向阶段头脑中形成的定向映象以外显的实际动作表现出来，也就是将头脑中的各种认识与实际的肌肉动作联系起来。（3）操作的整合阶段：个体把操作的模仿阶段习得的动作固定下来，并使各动作成分相结合，成为定型的、一体化的动作。（4）操作的熟练阶段：形成的动作方式对各种变化的条件具有高度的适应性，动作的执行达到高度的完善化和自动化。此处的自动化并非无意识的，而是指执行过程不需要意识的高度控制。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 114}}
]);
